<!--
 * 岗位管理页面 — 展示岗位列表，支持新增/编辑/删除岗位
 *
 * @path apps\userinfo-web\src\views\system\post\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 岗位（列表页）
 * <p>岗位（{@code ydsz_post}）的列表页，消费后端契约 PostController
 * （src/api/post.ts，auto-generated by bash/gen-contract.py）：
 * list() 拉取全量岗位（非分页，query 返回 { items, total: items.length }），
 * 支持新增/编辑/删除，搜索表单（岗位名称/编码）在本地过滤。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYdModal } from '@ydsz/common-ui';

import { YdBadge, YdButtonBase } from '@ydsz-core/ydsz-ui';
import { h } from 'vue';
import { useI18n } from 'vue-i18n';

import { createLogger } from '@ydsz-core/shared/utils';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { list, remove } from '#/api/post';
import type { PostVO } from '#/api/models';

import PostForm from './post-form.vue';

defineOptions({ name: 'PostManagement' });

const logger = createLogger('userinfo-post');
const { t } = useI18n();

/** 判断岗位状态是否启用（契约 status 为字符串 '1'/'0'） */
function isEnabled(status?: string): boolean {
  return status === '1';
}

const gridOptions: VxeTableGridOptions<PostVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('page.rowIndex') },
    { field: 'postName', title: t('page.postName'), minWidth: 150 },
    { field: 'postCode', title: t('page.postCode'), width: 150 },
    { field: 'description', title: t('page.description'), minWidth: 180 },
    { field: 'sortOrder', title: t('page.sortOrder'), width: 80, align: 'center' },
    {
      field: 'status',
      title: t('page.status'),
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            YdBadge,
            { variant: enable ? 'default' : 'destructive', class: enable ? 'bg-green-500 text-white hover:bg-green-600' : 'text-xs' },
            () => (enable ? t('page.enabled') : t('page.disabled')),
          );
        },
      },
    },
    {
      field: 'action',
      title: t('page.operation'),
      width: 140,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleEdit(row) },
              () => t('page.edit'),
            ),
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', class: 'text-destructive', onClick: () => handleDelete(row) },
              () => t('page.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const items = (await list()) ?? [];
        const keyword = String(formValues?.keyword ?? '').trim().toLowerCase();
        const filtered = keyword
          ? items.filter(
              (item) =>
                item.postName?.toLowerCase().includes(keyword) ||
                item.postCode?.toLowerCase().includes(keyword),
            )
          : items;
        return { items: filtered, total: filtered.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'YdInput',
        componentProps: { placeholder: t('post.keywordPlaceholder') },
        fieldName: 'keyword',
        label: t('post.keyword'),
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: t('page.search') },
    resetButtonOptions: { content: t('page.reset') },
  },
});

// ========== 表单弹窗 ==========
const [PostFormModal, postFormApi] = useYdModal({ connectedComponent: PostForm });

function handleAdd() {
  postFormApi.open();
}

function handleEdit(row: PostVO) {
  postFormApi.setData({ record: row });
  postFormApi.open();
}

// ========== 删除 ==========
async function handleDelete(row: PostVO) {
  if (!row.id) return;
  try {
    await YdConfirm(
      t('post.deletePostConfirm', { postName: row.postName ?? '' }),
      t('page.confirmDelete'),
      { type: 'warning' },
    );
    await remove({ id: row.id });
    showToast.success(t('page.deleteSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除岗位失败: {}', error);
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('post.postManagement')">
      <template #toolbar-tools>
        <YdButtonBase variant="default" @click="handleAdd">{{ t('post.createPost') }}</YdButtonBase>
      </template>
    </Grid>
    <PostFormModal @success="gridApi.query()" />
  </Page>
</template>